template <class F>
auto in_transaction(Db& db, F&& body) -> decltype(std::forward<F>(body)()) {
    db.begin();                                            // setup
    try {
        auto result = std::invoke(std::forward<F>(body));  // body
        db.commit();                                       // teardown: success
        return result;
    } catch (...) {
        db.rollback();                                     // teardown: failure
        throw;
    }
}

